import{_ as s,C as o,o as r,c as n,a6 as a,E as i}from"./chunks/framework.DIp0zHSV.js";const l="/dev/img/lcards-banner.gif",w=JSON.parse('{"title":"What is LCARdS?","description":"What LCARdS is: LCARS-style cards, a layout view and a shell dashboard for Home Assistant, with themes, rules, data sources, animations, sounds and alert modes, and how the pieces fit together.","frontmatter":{"description":"What LCARdS is: LCARS-style cards, a layout view and a shell dashboard for Home Assistant, with themes, rules, data sources, animations, sounds and alert modes, and how the pieces fit together."},"headers":[],"relativePath":"getting-started/what-is-lcards.md","filePath":"getting-started/what-is-lcards.md","lastUpdated":1792162559000}'),d={name:"getting-started/what-is-lcards.md"};function h(c,t,m,u,g,p){const e=o("HowItWorks");return r(),n("div",null,[t[0]||(t[0]=a('<h1 id="what-is-lcards" tabindex="-1">What is LCARdS? <a class="header-anchor" href="#what-is-lcards" aria-label="Permalink to &quot;What is LCARdS?&quot;">​</a></h1><p><img src="'+l+'" alt="LCARdS Banner"></p><p><strong>Build Star Trek LCARS-style dashboards in Home Assistant.</strong></p><p>LCARdS is a set of LCARS cards (buttons, elbows, sliders, charts, data grids, ship displays and more) that work together as one system. It is designed to pair with the <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS theme</a>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Three layers, plus a small integration running inside Home Assistant.</p>',6)),i(e),t[1]||(t[1]=a('<h2 id="what-that-gives-you" tabindex="-1">What that gives you <a class="header-anchor" href="#what-that-gives-you" aria-label="Permalink to &quot;What that gives you&quot;">​</a></h2><ul><li><strong>Colours that follow state:</strong> a button lights up when its light is on, a reading turns red past a threshold. No automations needed.</li><li><strong>One look everywhere:</strong> every card takes its colours, fonts and sizes from the same theme, so the whole screen matches.</li><li><strong>Screen-wide reactions:</strong> <a href="./../core/rules/">rules</a> restyle many cards at once, and <a href="./../core/alert-mode.html">alert mode</a> repaints the whole dashboard.</li><li><strong>Live values anywhere:</strong> put a sensor value, a smoothed reading or a <a href="./../core/templates/">template</a> in any label.</li><li><strong>Motion and sound:</strong> <a href="./../core/animations.html">animations</a> and LCARS <a href="./../core/sounds.html">sounds</a> on taps and state changes.</li><li><strong>Control from automations:</strong> <a href="./../configuration/ha-actions.html">actions</a> like <code>lcards.red_alert</code> work from scripts, automations and voice.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li><strong><a href="./installation.html">Install LCARdS</a></strong>: through HACS, in a few minutes.</li><li><strong><a href="./building-dashboards.html">Build a dashboard</a></strong>: pick cards and lay out a screen.</li><li><strong><a href="./dashboard-gallery.html">Browse the gallery</a></strong>: copy a complete dashboard and make it yours.</li><li><strong><a href="./ai-assistance.html">Get AI help</a></strong>: let an assistant write the YAML for you.</li></ol><div class="info custom-block"><p class="custom-block-title">A hobby project</p><p>LCARdS is a fan-made hobby project, not a fully commissioned Starfleet product: expect the occasional tribble. If something in these docs doesn&#39;t match what you see, please <a href="https://github.com/snootched/lcards/issues" target="_blank" rel="noreferrer">open an issue</a>.</p></div>',5))])}const _=s(d,[["render",h]]);export{w as __pageData,_ as default};
